<?php page_header('Track your recharge');page_intro('STAY IN THE LOOP','Where’s my top-up?','Enter your order or request reference and the email you used at checkout.'); ?>
<section class="container section compact narrow"><form class="surface" method="post" action="/track"><?=csrf()?><label for="order-number">Order or request ID</label><input id="order-number" name="order_number" maxlength="32" required placeholder="Your confirmation reference" value="<?=e($_POST['order_number']??'')?>"><label for="track-email">Email address</label><input id="track-email" type="email" name="email" autocomplete="email" maxlength="254" required value="<?=e($_POST['email']??'')?>"><?php if($error):?><p class="form-error" role="alert"><?=e($error)?></p><?php endif;?><button type="submit" class="button primary full">Check status <?=icon('search')?></button></form>
<?php if($order):?><div class="surface tracking-result"><h2>Your order update</h2><?php order_details($order);?><h3>Recharge progress</h3><ol class="timeline"><?php foreach(all('SELECT status,created_at FROM order_status_history WHERE order_id=? ORDER BY id',[$order['id']]) as $h):?><li><?=status_badge($h['status'])?><time><?=e(when($h['created_at']))?></time></li><?php endforeach;?></ol><p class="muted">Need help? Email <?=e(setting('support_email','info@mitechwireless.com'))?> with your order ID.</p></div><?php endif;?>
<?php if($request):?><div class="surface tracking-result"><h2>Your request update</h2><div class="order-states"><div><span>Payment</span><?=status_badge('awaiting_payment')?></div><div><span>Request</span><?=status_badge('submitted')?></div></div><dl class="order-details"><?php foreach(['Reference'=>$request['reference'],'Carrier'=>$request['carrier_name'],'Plan'=>$request['plan_name'],'Mobile number'=>format_phone($request['recharge_phone']),'Plan price'=>money($request['amount_cents']),'Submitted'=>when($request['completed_at'])] as $key=>$value):?><div><dt><?=e($key)?></dt><dd><?=e($value)?></dd></div><?php endforeach;?></dl><p class="muted">Your request is awaiting payment arrangements. No payment has been collected and your recharge has not yet been fulfilled. Contact <?=e(setting('support_email','info@mitechwireless.com'))?> with your reference for assistance.</p></div><?php endif;?></section><?php page_footer(); ?>
